#include "../src/game/later_falling_doll.hpp"
#include "../src/game/later_springs.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::IndexedSurface f(640,480);shin::LaterSprings s;for(int t:{0x5b,0x5e}){s.spawn(t,100,100,t);a.image(s.resource(t));}s.tick(0,0,a,f);for(auto&e:s.objects){e.e.at(0x50)=1;e.e.at(0x28)=3;}for(int i=0;i<35;++i)s.tick(0,0,a,f);for(auto&e:s.objects)assert(e.e.at(0x50)==0);shin::LaterFallingDoll d(200,100);d.tick(0,0,a,f);d.tick(0,0,a,f);assert(d.e.at(4)==194&&d.e.at(8)==93);shin::MapData map{8,8,std::vector<shin::MapCell>(64)};for(auto&c:map.cells)c.foreground_tile=-1;shin::AppImage block{32,32,std::vector<unsigned char>(1024,1)};shin::game::CollisionWorld w(map,block);d.e.at(0x40)=4;d.terrain(w,1);assert(d.e.at(0x40)==-4&&d.e.at(0x44)==1);for(int x=0;x<8;++x)map.cells[3*8+x].foreground_tile=0;d.e.at(4)=0;d.e.at(8)=0;d.e.at(0x40)=4;assert(w.body(d.rectangle(),0,0)==1);d.terrain(w,1);assert(d.e.at(8)==-14&&d.e.at(0x40)==-4);d.e.at(8)=0;d.e.at(0x40)=4;d.terrain(w,2);assert(d.e.at(8)==-14&&d.e.at(0x40)==-6);d.terrain(w,5);assert(d.e.state==2);}
